#!/usr/bin/env node

/**
 * Bulk Create Subscriptions Script
 * 
 * Creates subscription products in App Store Connect from a JSON file
 * generated by generate-product-ids.js
 * 
 * Usage:
 *   node bulk-create-subscriptions.js <json-file-path> [--dry-run]
 *   npm run bulk-create-subs -- product-ids-test3.json
 *   npm run bulk-create-subs -- product-ids-test3.json --dry-run
 */

const fs = require('fs');
const path = require('path');
const appService = require('./src/services/apps');
const subscriptionService = require('./src/services/subscriptions');
const logger = require('./src/utils/logger');

const BUNDLE_ID = 'com.vtech.plus.inapp.ios.test3';

/**
 * Convert duration string to App Store Connect subscription period
 * @param {string} duration - Duration from CSV (e.g., "1 MONTH", "1 YEAR")
 * @returns {string} App Store Connect subscription period
 */
function convertDuration(duration) {
  const durationMap = {
    '1 WEEK': 'ONE_WEEK',
    '1 MONTH': 'ONE_MONTH',
    '2 MONTHS': 'TWO_MONTHS',
    '3 MONTHS': 'THREE_MONTHS',
    '6 MONTHS': 'SIX_MONTHS',
    '1 YEAR': 'ONE_YEAR'
  };
  
  const normalized = duration.toUpperCase().trim();
  return durationMap[normalized] || 'ONE_MONTH';
}

/**
 * Display help message
 */
function showHelp() {
  console.log(`
Bulk Create Subscriptions from JSON

Usage:
  node bulk-create-subscriptions.js <json-file-path> [options]
  npm run bulk-create-subs -- <json-file-path> [options]

Arguments:
  json-file-path    Path to the JSON file (output from generate-product-ids.js)

Options:
  --dry-run         Preview what would be created without making changes
  --help, -h        Show this help message

Examples:
  node bulk-create-subscriptions.js product-ids-test3.json
  node bulk-create-subscriptions.js product-ids-test3.json --dry-run
  npm run bulk-create-subs -- product-ids-test3.json

Process:
  1. Reads the JSON file with subscription data
  2. Fetches existing subscription groups from App Store Connect
  3. Creates missing subscription groups
  4. Creates subscriptions in each group
  5. Reports success/failure for each operation
`);
}

/**
 * Find or create subscription group
 * @param {string} appId - App Store Connect app ID
 * @param {string} groupName - Reference name for the group
 * @param {Array} existingGroups - Array of existing groups
 * @param {boolean} dryRun - If true, don't actually create
 * @returns {Object} Group object with id and referenceName
 */
async function findOrCreateGroup(appId, groupName, existingGroups, dryRun) {
  // Check if group already exists
  const existing = existingGroups.find(g => 
    g.referenceName.toLowerCase() === groupName.toLowerCase()
  );
  
  if (existing) {
    console.log(`  [EXISTS] Group: ${groupName} (ID: ${existing.id})`);
    return existing;
  }
  
  if (dryRun) {
    console.log(`  [DRY-RUN] Would create group: ${groupName}`);
    return { id: 'dry-run-id', referenceName: groupName };
  }
  
  // Create new group
  console.log(`  [CREATE] Creating group: ${groupName}`);
  try {
    const response = await appService.createSubscriptionGroup(appId, {
      referenceName: groupName
    });
    
    const newGroup = {
      id: response.data.id,
      referenceName: response.data.attributes.referenceName
    };
    
    console.log(`  [SUCCESS] Created group: ${groupName} (ID: ${newGroup.id})`);
    return newGroup;
  } catch (error) {
    console.error(`  [ERROR] Failed to create group ${groupName}: ${error.message}`);
    throw error;
  }
}

/**
 * Create a subscription
 * @param {Object} subscriptionData - Subscription data
 * @param {string} groupId - Subscription group ID
 * @param {boolean} dryRun - If true, don't actually create
 */
async function createSubscription(subscriptionData, groupId, dryRun) {
  const subscriptionPeriod = convertDuration(subscriptionData.duration);
  
  const payload = {
    name: subscriptionData.referenceName || subscriptionData.name,
    productId: subscriptionData.productId,
    subscriptionPeriod: subscriptionPeriod,
    subscriptionGroupId: groupId,
    familySharable: false,
    reviewNote: ''
  };
  
  if (dryRun) {
    console.log(`    [DRY-RUN] Would create: ${payload.productId}`);
    console.log(`              Name: ${payload.name}`);
    console.log(`              Period: ${payload.subscriptionPeriod}`);
    return { success: true, dryRun: true };
  }
  
  try {
    const response = await subscriptionService.createSubscription(payload);
    console.log(`    [SUCCESS] Created: ${payload.productId}`);
    return { success: true, data: response.data };
  } catch (error) {
    console.error(`    [ERROR] Failed to create ${payload.productId}: ${error.message}`);
    return { success: false, error: error.message };
  }
}

/**
 * Check if subscription already exists
 * @param {string} productId - Product ID to check
 * @param {Array} existingProductIds - Array of existing product IDs
 * @returns {boolean}
 */
function subscriptionExists(productId, existingProductIds) {
  return existingProductIds.includes(productId);
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);
  
  // Check for help flag
  if (args.includes('--help') || args.includes('-h')) {
    showHelp();
    process.exit(0);
  }
  
  // Check for dry-run flag
  const dryRun = args.includes('--dry-run');
  const jsonPath = args.find(arg => !arg.startsWith('--'));
  
  if (!jsonPath) {
    console.error('Error: JSON file path is required\n');
    showHelp();
    process.exit(1);
  }
  
  if (!fs.existsSync(jsonPath)) {
    console.error(`Error: File not found: ${jsonPath}`);
    process.exit(1);
  }
  
  console.log('='.repeat(70));
  console.log('Bulk Create Subscriptions');
  console.log('='.repeat(70));
  
  if (dryRun) {
    console.log('\n[DRY-RUN MODE] No changes will be made\n');
  }
  
  try {
    // Read JSON file
    const data = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
    console.log(`\nSource file: ${jsonPath}`);
    console.log(`Bundle ID: ${data.bundleId || BUNDLE_ID}`);
    console.log(`Subscription Groups: ${data.subscriptionGroups.length}`);
    console.log(`Total Subscriptions: ${data.totalCount}`);
    
    // Get app information and existing data
    console.log('\nFetching existing data from App Store Connect...');
    const existingData = await appService.getSubscriptionProductIdsByBundleId(
      data.bundleId || BUNDLE_ID,
      { useCache: false }
    );
    
    const appId = existingData.appId;
    const existingGroups = existingData.subscriptionGroups;
    const existingProductIds = existingData.productIds;
    
    console.log(`\nApp ID: ${appId}`);
    console.log(`Existing Groups: ${existingGroups.length}`);
    console.log(`Existing Subscriptions: ${existingProductIds.length}`);
    
    // Track results
    const results = {
      groupsCreated: 0,
      groupsExisting: 0,
      subscriptionsCreated: 0,
      subscriptionsExisting: 0,
      subscriptionsFailed: 0
    };
    
    // Process each subscription group
    console.log('\n' + '-'.repeat(70));
    console.log('Processing Subscription Groups');
    console.log('-'.repeat(70));
    
    for (const group of data.subscriptionGroups) {
      console.log(`\nGroup: ${group.groupName}`);
      
      // Find or create the group
      let groupRecord;
      try {
        groupRecord = await findOrCreateGroup(appId, group.groupName, existingGroups, dryRun);
        
        if (existingGroups.find(g => g.id === groupRecord.id)) {
          results.groupsExisting++;
        } else {
          results.groupsCreated++;
          // Add to existing groups for subsequent lookups
          existingGroups.push(groupRecord);
        }
      } catch (error) {
        console.error(`  Skipping group ${group.groupName} due to error`);
        continue;
      }
      
      // Create subscriptions in this group
      for (const subscription of group.subscriptions) {
        if (subscriptionExists(subscription.productId, existingProductIds)) {
          console.log(`    [EXISTS] ${subscription.productId}`);
          results.subscriptionsExisting++;
          continue;
        }
        
        const result = await createSubscription(subscription, groupRecord.id, dryRun);
        
        if (result.success) {
          results.subscriptionsCreated++;
          existingProductIds.push(subscription.productId);
        } else {
          results.subscriptionsFailed++;
        }
        
        // Add a small delay to avoid rate limiting
        if (!dryRun) {
          await new Promise(resolve => setTimeout(resolve, 500));
        }
      }
    }
    
    // Print summary
    console.log('\n' + '='.repeat(70));
    console.log('Summary');
    console.log('='.repeat(70));
    console.log(`\nSubscription Groups:`);
    console.log(`  Created: ${results.groupsCreated}`);
    console.log(`  Already Existed: ${results.groupsExisting}`);
    console.log(`\nSubscriptions:`);
    console.log(`  Created: ${results.subscriptionsCreated}`);
    console.log(`  Already Existed: ${results.subscriptionsExisting}`);
    console.log(`  Failed: ${results.subscriptionsFailed}`);
    
    if (dryRun) {
      console.log('\n[DRY-RUN] No changes were made. Remove --dry-run to execute.');
    }
    
    // Exit with error code if any failures
    if (results.subscriptionsFailed > 0) {
      process.exit(1);
    }
    
  } catch (error) {
    console.error(`\nFatal error: ${error.message}`);
    logger.error('Bulk create subscriptions failed:', error);
    process.exit(1);
  }
}

main();
